(()=>{const D=window.CITYWIDE,$=id=>document.getElementById(id),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));let limit=100;$('stats').innerHTML=`<div><strong>${D.records.length.toLocaleString()}</strong>facilities in source</div><div><strong>${D.records.filter(r=>r.officeCandidate).length}</strong>office / training / testing candidates</div><div><strong>${D.records.filter(r=>r.operatorType==='Public').length.toLocaleString()}</strong>public-operated facilities</div>`;$('borough').innerHTML+=[...new Set(D.records.map(r=>r.borough).filter(Boolean))].sort().map(b=>`<option>${esc(b)}</option>`).join('');$('source').textContent=`Source: NYC Planning Facilities Database (ji82-xba5). Source updated ${D.sourceUpdated.slice(0,10)}. Retrieved ${D.retrieved.slice(0,10)}. Not a verified census of public-facing service counters.`;function render(){const q=$('search').value.toLowerCase(),scope=$('scope').value,borough=$('borough').value;const verified=window.SCHEDULE_DATA.records.filter(r=>r.channel==='in_person'&&r.status!=='closed').map(r=>({name:r.name,address:r.address,borough:r.borough.toUpperCase(),type:r.service,group:r.category,operator:r.agency,operatorType:'Confirmed service location',hours:r.hoursText,sourceUrl:r.sourceUrl}));const rs=(scope==='verified'?verified:D.records).filter(r=>(scope==='verified'||scope==='all'||scope==='public'&&r.operatorType==='Public'||scope==='office'&&r.officeCandidate)&&(borough==='all'||r.borough===borough)&&(!q||[r.name,r.address,r.operator,r.agency].join(' ').toLowerCase().includes(q)));$('count').textContent=`${rs.length.toLocaleString()} records · showing ${Math.min(limit,rs.length)}`;$('rows').innerHTML=rs.slice(0,limit).map(r=>`<tr><td>${esc(r.name)}</td><td>${esc(r.address)}<small>${esc(r.borough)}</small></td><td>${esc(r.type)}<small>${esc(r.group)}</small></td><td>${esc(r.operator||r.agency)}<small>${esc(r.operatorType)}</small></td><td>${r.hours?esc(r.hours):'Hours unknown'}<small>${r.hours?`<a href="${esc(r.sourceUrl)}" target="_blank" rel="noopener">Official source ↗</a>`:'Public-facing access unverified'}</small></td></tr>`).join('');$('more').hidden=limit>=rs.length;}$('search').oninput=()=>{limit=100;render();};$('scope').onchange=$('borough').onchange=()=>{limit=100;render();};$('more').onclick=()=>{limit+=100;render();};render();})();
